import {renderHeader,renderFooter,escapeHTML as e} from '../explorer-views.js';
import {startingPointBank as bank,startingQuestions,startingOption,text} from './starting-point.js';
export const ui=(locale,en,zh,ms)=>({en,'zh-CN':zh,ms})[locale]||en;
const sections=[['Understand Your Concerns','了解你真正的困惑','Fahami kebimbangan anda'],['Understand Your Starting Point','了解你目前拥有的能力','Fahami titik permulaan anda'],['Understand Your Ambitions','了解你真正想走向哪里','Fahami cita-cita anda'],['A Little More Context','进一步了解你的处境','Sedikit lagi konteks'],['Your Story','你的补充','Cerita anda']];
function choices(q,intake,locale,part){
 const multiple=q.kind==='multi',value=part?intake.answers[q.id]?.[part]:intake.answers[q.id];
 return `<div class="starting-choices">${q.options.map(o=>{
  const checked=multiple?value?.includes(o.id):value===o.id;
  return `<label class="starting-choice ${checked?'is-selected':''}"><input type="${multiple?'checkbox':'radio'}" name="${e(q.id+(part?'.'+part:''))}" data-starting-field="${e(q.id+(part?'.'+part:''))}" value="${e(o.id)}" ${checked?'checked':''} ${multiple&&!checked&&value?.length===2?'disabled':''}><span><strong>${e(text(o.label,locale))}</strong>${o.description?`<small>${e(text(o.description,locale))}</small>`:''}</span><span class="starting-choice-check" aria-hidden="true">${checked?'✓':'+'}</span></label>`;
 }).join('')}</div>`;
}
function controls(q,intake,locale){
 const L=(en,zh,ms)=>ui(locale,en,zh,ms);
 if(q.kind==='story')return `<p>${L('Optional. You can skip this. Your story stays on this device unless you separately consent to sharing it with optional AI.','选填，可以直接跳过。补充内容保留在本机，只有另行明确同意后才会随可选 AI 分析发送。','Pilihan. Anda boleh melangkau. Cerita kekal pada peranti ini kecuali anda memberi persetujuan berasingan untuk AI pilihan.')}</p><textarea id="starting-story" name="story" data-starting-story maxlength="1500" rows="6" placeholder="${e(text(bank.story.placeholder,locale))}" aria-labelledby="starting-heading">${e(intake.story)}</textarea><small class="starting-story-count">${intake.story.length} / 1500</small>`;
 if(q.kind==='matrix')return `<p>${L('Answer from actual learning or work experience, not your hoped-for future level. This is a self-report, not a verified skills test.','请根据真实学习或工作经历作答，而不是根据你觉得自己未来可能做到什么来选择。这是自述能力，不是已验证的专业能力。','Jawab berdasarkan pengalaman belajar atau kerja sebenar, bukan tahap masa depan yang diharapkan. Ini laporan kendiri, bukan ujian kemahiran disahkan.')}</p><div class="starting-matrix">${q.rows.map(row=>`<fieldset><legend>${e(text(row.label,locale))}</legend><div class="starting-matrix-options">${q.options.map(o=>`<label class="${intake.answers.Q05?.[row.id]===o.id?'is-selected':''}"><input type="radio" name="Q05.${row.id}" data-starting-field="Q05.${row.id}" value="${o.id}" ${intake.answers.Q05?.[row.id]===o.id?'checked':''}><span>${e(text(o.label,locale))}</span></label>`).join('')}</div></fieldset>`).join('')}</div><details class="starting-level-guide"><summary>${L('What each level means','各等级的含义','Maksud setiap tahap')}</summary>${q.options.map(o=>`<p><strong>${e(text(o.label,locale))}</strong> — ${e(text(o.description,locale))}</p>`).join('')}</details>`;
 if(q.kind==='priority')return `<p>${L('Choose your main concern first. You may add one secondary concern. This sets the report focus, not an ability score.','先选择 1 项最主要的困惑，可再选 1 项次要困惑。这决定报告重点，不直接判断能力水平。','Pilih kebimbangan utama dahulu. Anda boleh menambah satu kebimbangan kedua. Ini menentukan fokus laporan, bukan skor kebolehan.')}</p>${choices(q,intake,locale,'primary')}<label class="starting-secondary" for="starting-secondary">${L('Secondary concern (optional)','次要困惑（可选）','Kebimbangan kedua (pilihan)')}</label><select id="starting-secondary" name="Q02.secondary" data-starting-field="Q02.secondary"><option value="">${L('None','不选择','Tiada')}</option>${q.options.filter(o=>o.id!==intake.answers.Q02?.primary).map(o=>`<option value="${o.id}" ${intake.answers.Q02?.secondary===o.id?'selected':''}>${e(text(o.label,locale))}</option>`).join('')}</select>`;
 return `${q.kind==='multi'?`<p>${L('Select up to two obstacles. These are your perceived barriers, not measured skill deficits.','最多选 2 项。这里记录你感受到的障碍，不将它们当作已测量的能力缺口。','Pilih sehingga dua halangan. Ini halangan yang anda rasai, bukan kekurangan kemahiran yang diukur.')}</p>`:''}${choices(q,intake,locale)}`;
}
export function renderStartingPoint(intake,locale='en',error='',motion=''){
 const L=(en,zh,ms)=>ui(locale,en,zh,ms),questions=startingQuestions(intake.answers),q=questions[intake.index];
 const top=`<div class="starting-top"><button class="text-button" type="button" data-combined-action="${intake.screen==='intro'?'home':'starting-back'}">← ${L(intake.screen==='intro'?'Back to home':'Back',intake.screen==='intro'?'返回首页':'上一题',intake.screen==='intro'?'Kembali ke laman utama':'Kembali')}</button><span>${L('Your future, in context','从你的真实处境出发','Masa depan anda, dalam konteks')}</span></div>`;
 let body;
 if(intake.screen==='intro')body=`<section class="starting-card starting-intro"><span class="kicker">AI CAREER NAVIGATOR</span><h1 id="starting-heading" tabindex="-1">${L('Your Future Starts With Understanding You','在规划未来之前，我们想先了解你。','Masa depan bermula dengan memahami diri anda.')}</h1><p class="hero-lede">${L('AI is changing careers, but everyone faces different challenges.','AI 正在改变职业世界，但每个人面对的挑战都不同。','AI mengubah dunia kerjaya, tetapi cabaran setiap orang berbeza.')}</p><p>${L('You may worry that your skills will lose value, feel unsure about career fit, or see AI and international opportunities without knowing where to begin.','也许你担心现在学习的技能很快失去价值，也许你不知道自己适合什么职业，或者你看到了 AI 和国际市场创造的新机会，却不知道该从哪里开始。','Anda mungkin bimbang kemahiran kehilangan nilai, belum pasti arah kerjaya, atau melihat peluang AI dan antarabangsa tanpa mengetahui langkah pertama.')}</p><p>${L('This is not an exam. There are no right answers. We want to understand your situation, then connect your characteristics with career information to help you find a next step.','这不是一场考试，也没有标准答案。我们希望先了解你的真实处境，再结合你的个人特点与职业市场信息，帮助你找到下一步。','Ini bukan peperiksaan dan tiada jawapan betul. Kami mahu memahami keadaan anda, kemudian mengaitkan ciri diri dengan maklumat kerjaya untuk membantu menentukan langkah seterusnya.')}</p><div class="starting-meta">${L('3–4 minutes · 9 core questions · up to 2 follow-ups','预计用时：3–4 分钟 · 9 个核心问题 · 最多 2 个补充问题','3–4 minit · 9 soalan teras · sehingga 2 soalan susulan')}</div><button class="button primary" data-combined-action="starting-next">${L('Let’s begin','开始了解自己','Mari bermula')} ↗</button></section>`;
 else if(intake.screen==='bridge')body=`<section class="starting-card"><span class="kicker">${L('Your starting point','你的起点','Titik permulaan anda')}</span><h1 id="starting-heading" tabindex="-1">${L("Here’s What We Understand About You",'我们初步了解到的你','Inilah yang kami fahami tentang anda')}</h1><p class="hero-lede">${L('We now have context about your current stage, main concern, reported experience and goals. Next, a few short questions will explore career interests, work preferences and AI collaboration habits.','根据你的回答，我们初步了解到你的当前阶段、主要困惑、已有经历与发展目标。接下来，我们希望通过一些简短问题，进一步了解你的职业兴趣、工作偏好和 AI 协作习惯。','Kami kini mempunyai konteks tahap semasa, kebimbangan utama, pengalaman dilaporkan dan matlamat anda. Seterusnya, beberapa soalan ringkas akan meneroka minat kerjaya, keutamaan kerja dan amalan kerjasama AI.')}</p><dl class="starting-bridge-summary">${[['Q01',null,L('Current stage','当前阶段','Tahap semasa')],['Q02','primary',L('Main concern','主要困惑','Kebimbangan utama')],['Q08',null,L('Desired outcome','希望得到的结果','Hasil diharapkan')],['Q09',null,L('Market perspective','市场视角','Perspektif pasaran')]].map(([id,part,label])=>`<div><dt>${label}</dt><dd>${e(startingOption(intake,id,locale,part))}</dd></div>`).join('')}</dl><p>${L('Your current background does not decide your future direction. You can explore directions before trying one.','当前背景不替你决定未来方向。你可以先了解各方向，再选择一个开始体验。','Latar semasa tidak menentukan arah masa depan. Anda boleh meneroka arah sebelum mencubanya.')}</p><button class="button primary" data-combined-action="starting-continue">${L('Explore career directions','探索职业方向','Terokai arah kerjaya')} ↗</button></section>`;
 else body=`<section class="starting-card" data-starting-question="${q.id}"><div class="starting-progress-top"><span>${q.id} · ${ui(locale,...sections[q.section])}</span><span>${intake.index+1} / ${questions.length}</span></div><div class="progress-track" role="progressbar" aria-label="${L('Questionnaire progress','问卷进度','Kemajuan soal selidik')}" aria-valuemin="0" aria-valuemax="${questions.length}" aria-valuenow="${intake.index+1}"><div style="width:${(intake.index+1)/questions.length*100}%"></div></div><h1 id="starting-heading" tabindex="-1">${e(text(q.prompt,locale))}</h1><form id="starting-point-form" novalidate>${controls(q,intake,locale)}${error?`<p class="field-error" role="alert">${error==='multi'?L('Choose one or two options.','请选择 1 至 2 项。','Pilih satu atau dua pilihan.'):error==='matrix'?L('Choose one level for each of the four aspects.','请为四个方面各选择一项。','Pilih satu tahap bagi setiap empat aspek.'):L('Please choose an answer to continue.','请选择答案后继续。','Sila pilih jawapan untuk meneruskan.')}</p>`:''}<div class="starting-actions"><button class="button secondary" type="button" data-combined-action="starting-back">← ${L('Back','上一题','Kembali')}</button><button class="button primary" type="submit">${L(q.kind==='story'&&!intake.story?'Skip and continue':'Continue',q.kind==='story'&&!intake.story?'跳过并继续':'下一题',q.kind==='story'&&!intake.story?'Langkau dan teruskan':'Teruskan')} ↗</button></div></form></section>`;
 return renderHeader({report:null})+`<main class="shell starting-shell">${top}<div class="starting-transition ${motion?'is-moving '+motion:''}" data-starting-transition>${body}</div></main>`+renderFooter();
}
